-- =====================================================================
-- Migration 009 (Media / The Screening): Rockstar's own media collections as listed on its Media pages, https://www.rockstargames.com/VI/media, checked on 2026-10-20.
-- NON-DESTRUCTIVE and IDEMPOTENT: creates two new tables if they are missing, adds 92 official media rows that were not yet recorded (explicit ids from 115), and
-- lists every official picture, video and clip in Rockstar's own order. No DROP, no DELETE, no TRUNCATE; no existing row is changed and no ALTER is made.
-- Run after 001 to 008. Apply with: python -m scripts.migrate_db --only 009_media_screening.sql --plan   then   python -m scripts.migrate_db --only 009_media_screening.sql
--
--   * media_assets stays the one record of each official file. The new rows are linked to NO character, region or vehicle, so the Characters, Regions and Garage pages are not changed by them.
--   * media_collections holds Rockstar's section names with their source page and, where Rockstar offers one, its zip download and that file's size in bytes.
--   * media_collection_items holds the order inside each section and Rockstar's own title for each item. For a video it also holds the date, runtime and description Rockstar gives, and its poster.
--   * Titles, dates, runtimes and descriptions are Rockstar's words, copied from its pages; nothing is invented. Where Rockstar gives only a title, only the title is stored.
--   * Pictures are Rockstar's own files, referenced at its image address and never copied; every new address was requested before it was recorded.
-- =====================================================================

CREATE TABLE IF NOT EXISTS media_collections (
    collection_id   SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
    slug            VARCHAR(60)   NOT NULL,
    title           VARCHAR(100)  NOT NULL,
    kind            ENUM('video','clip','image') NOT NULL,
    sort_order      TINYINT UNSIGNED NOT NULL,
    source_url      VARCHAR(500)  NULL,
    download_url    VARCHAR(500)  NULL,
    download_bytes  BIGINT UNSIGNED NULL,
    content_status  ENUM('official','fan','demo') NOT NULL,
    source_note     VARCHAR(500)  NULL,
    verified_on     DATE          NULL,
    created_at      TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (collection_id),
    UNIQUE KEY uq_media_collections_slug (slug),
    UNIQUE KEY uq_media_collections_title (title),
    CONSTRAINT ck_media_collections_official_source
        CHECK (content_status <> 'official' OR source_url IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS media_collection_items (
    collection_id   SMALLINT UNSIGNED NOT NULL,
    position        SMALLINT UNSIGNED NOT NULL,
    media_id        INT UNSIGNED  NOT NULL,
    title           VARCHAR(160)  NOT NULL,
    published_on    DATE          NULL,
    runtime_seconds SMALLINT UNSIGNED NULL,
    description     VARCHAR(700)  NULL,
    poster_media_id INT UNSIGNED  NULL,
    PRIMARY KEY (collection_id, position),
    UNIQUE KEY uq_media_collection_items_media (collection_id, media_id),
    KEY ix_media_collection_items_media (media_id),
    KEY ix_media_collection_items_poster (poster_media_id),
    CONSTRAINT fk_mci_collection FOREIGN KEY (collection_id)
        REFERENCES media_collections (collection_id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_mci_media FOREIGN KEY (media_id)
        REFERENCES media_assets (media_id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_mci_poster FOREIGN KEY (poster_media_id)
        REFERENCES media_assets (media_id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

AS new ON DUPLICATE KEY UPDATE title = new.title, media_type = new.media_type, intended_use = new.intended_use, source_url = new.source_url, embed_url = new.embed_url, usage_status = new.usage_status, approval_status = new.approval_status;

AS new ON DUPLICATE KEY UPDATE title = new.title, kind = new.kind, sort_order = new.sort_order, source_url = new.source_url, download_url = new.download_url, download_bytes = new.download_bytes,
    content_status = new.content_status, source_note = new.source_note, verified_on = new.verified_on;

AS new ON DUPLICATE KEY UPDATE media_id = new.media_id, title = new.title, published_on = new.published_on, runtime_seconds = new.runtime_seconds, description = new.description, poster_media_id = new.poster_media_id;
